from pathlib import Path
p=Path(__file__).parents[1]/'frontend'/'src'/'main.ts'
s=p.read_text(encoding='utf-8-sig')
s=s.replace('<section class="ride-scene card">', '<section class="ride-scene card" :class="{\'training-view\':view!==\'ride\'}">')
s=s.replace('<span class="scene-tag"><Mountain :size="14"/> DEIN FREIRAUM</span>', '''<div class="view-switch" aria-label="Cockpit-Ansicht"><button :class="{chosen:view===name}" v-for="(label,name) in {ride:'Rad',timeline:'Zeitachse',mountain:'Berg'}" @click="setView(name)">{{label}}</button></div>''')
s=s.replace('<div class="scene-copy">', '<div v-if="view===\'ride\'" class="scene-copy">')
s=s.replace('<svg class="landscape"','<svg v-if="view===\'ride\'" class="landscape"')
s=s.replace('<div class="scene-footer">', '''<WorkoutTimeline v-if="view==='timeline'" :steps="previewSteps" :elapsed="previewElapsed" :samples="state.running||!selectedPlan?state.samples||[]:[]" :power="state.power" :target="state.target" :ftp="profile.ftp_watts||150"/><PowerMountain v-if="view==='mountain'" :watts="state.running?state.power:state.target" :ftp="profile.ftp_watts||150"/>
      <div class="scene-footer">''')
s=s.replace("{{state.plan_name || 'Freies Training'}}", "{{state.running?state.plan_name:selectedPlan?.name||state.plan_name||'Freies Training'}}")
s=s.replace("{{state.step_name || 'Dein Tempo zählt'}}", "{{state.running?state.step_name:selectedPlan?'Planvorschau':state.step_name}} {{state.running&&state.steps?.length?'· '+clock(state.step_remaining):''}}")
s=s.replace(':disabled="busy||!online||state.zwift_detail?.armed" @click="setPower', ':disabled="manualLocked" @click="setPower')
s=s.replace(':disabled="busy||!online||state.zwift_detail?.armed" @change="setPower', ':disabled="manualLocked" @change="setPower')
s=s.replace('<span class="tiny-badge">ERG</span>', '<span class="tiny-badge">{{state.running&&state.training_mode===\'hr\'?\'PULS\':\'ERG\'}}</span>')
s=s.replace("{{state.paused?'Pausiert':state.running?'Dein Ride läuft':'Bereit für den Start'}}", "{{state.paused?'Pausiert':state.running&&state.duration?'Noch '+clock(state.duration-state.elapsed):state.running?'Dein Ride läuft':'Bereit für den Start'}}")
s=s.replace("modal==='hr'?'Pulsgurt verbinden':'Einstellungen'", "modal==='hr'?'Pulsgurt verbinden':modal==='profile'?'Persönliche Trainingswerte':'Einstellungen'")

toolbar='''
    <section class="training-toolbar card"><label class="training-select">Training<select aria-label="Training auswählen" v-model="selected" :disabled="state.running||busy"><option :value="null">Freies Training / Puls-Cardio</option><option v-for="plan in plans" :value="plan.id">{{plan.name}} · {{duration(plan)}} min</option></select></label><div class="mode-choice" aria-label="Trainingssteuerung"><button :class="{chosen:trainingMode==='power'}" :disabled="state.running" @click="trainingMode='power'">Wattgeführt</button><button :class="{chosen:trainingMode==='hr'}" :disabled="state.running" @click="trainingMode='hr'">Pulsgeführt</button></div><label v-if="selectedPlan" class="intensity-control">Watt-Intensität · {{intensity}} %<input aria-label="Trainingsintensität in Prozent" type="range" min="50" max="130" step="5" v-model.number="intensity" :disabled="state.running||trainingMode==='hr'"></label><button class="text-button" @click="openProfile">Persönliche Werte <Settings2 :size="15"/></button><p v-if="selectedPlan?.requires_ftp" class="training-hint">Beispielwerte bei 150 W FTP. Vor dem Start persönliche FTP hinterlegen; keine individuelle Vorgabe.</p><div v-if="trainingMode==='hr'" class="hr-setup"><span><Heart :size="16"/>{{profile.hr_max?'HFmax '+profile.hr_max+' · Pulsgrenze '+(profile.hr_ceiling||'fehlt')+' bpm':'Zuerst persönliche HFmax und Pulsgrenze eintragen.'}}</span><template v-if="!selectedPlan"><label>Dauer<select v-model.number="cardioMinutes" :disabled="state.running"><option :value="35">35 min</option><option :value="45">45 min</option><option :value="60">60 min</option></select></label><label>Pulsziel von<input v-model.number="hrLow" type="number" :placeholder="profile.hr_max?Math.round(profile.hr_max*.60):'bpm'" :disabled="state.running"></label><label>bis<input v-model.number="hrHigh" type="number" :placeholder="profile.hr_max?Math.round(profile.hr_max*.70):'bpm'" :disabled="state.running"></label></template><small>Nur mit frischem Gurtsignal. Wattgrenze {{profile.hr_max_watts}} W; kein künstlicher Puls in der Demo.</small></div></section>
    <section v-if="state.running&&state.training_mode==='hr'" class="pulse-live card"><Heart :size="24"/><div><span>DEINE PULS-ZIELZONE</span><b>{{state.hr_target?.low}}–{{state.hr_target?.high}} <small>bpm</small></b></div><div class="pulse-live-current"><span>AKTUELL</span><b>{{state.heart_rate??'—'}} <small>bpm</small></b></div><p>{{state.pulse_status}}</p></section>
'''
s=s.replace("<template v-if=\"tab==='Cockpit'\">", "<template v-if=\"tab==='Cockpit'\">"+toolbar)

start=s.index('   <template v-if="tab===\'Trainingspläne\'">')
end=s.index('   <template v-if="tab===\'Verbindungen\'">',start)
s=s[:start]+'''   <template v-if="tab==='Trainingspläne'">
    <section class="training-intro card"><div><p class="eyebrow">AUSDAUER AUFBAUEN · DOSIERT STEIGERN</p><h2>Dein Plan für mehr Kondition.</h2><p>Grundlage, Tempo und aerobe Intervalle in 35, 45 oder 60 Minuten. Wattwerte sind veränderbare Startpunkte relativ zur FTP; sie sind keine universellen Trainingsvorgaben.</p><span class="profile-summary">{{profile.ftp_watts?'Deine FTP: '+profile.ftp_watts+' W':'Vorschau mit 150 W Beispiel-FTP · Start erst mit persönlicher FTP'}}</span></div><button class="button secondary" @click="openProfile">Persönliche Werte</button></section>
    <div class="plan-filters"><div class="duration-choice"><button v-for="minutes in [0,35,45,60]" :class="{chosen:filterMinutes===minutes}" @click="filterMinutes=minutes">{{minutes?minutes+' min':'Alle Dauern'}}</button></div><label>Ziel<select v-model="filterCategory" aria-label="Trainingsziel filtern"><option v-for="goal in ['Alle','Grundlage','Tempo','VO₂max','Eigene']">{{goal}}</option></select></label><button class="button primary" @click="modal='plan'"><Plus :size="17"/>Plan erstellen</button></div>
    <div class="plan-grid"><article class="card plan-card" v-for="(plan,i) in visiblePlans" :key="plan.id"><div class="plan-art" :class="{orange:plan.meta?.category==='VO₂max'}"><Mountain :size="52"/><span>{{duration(plan)}}<small>MINUTEN</small></span></div><p class="eyebrow">{{plan.meta?.category||'EIGENES TRAINING'}} · {{plan.steps.length}} ABSCHNITTE</p><h2>{{plan.name}}</h2><div class="interval-bars"><i v-for="step in plan.steps" :style="{height:Math.max(8,step.watts/(profile.ftp_watts||150)*60)+'px',flex:step.seconds}" :class="step.zone" :title="step.name+': '+step.watts+' W'"></i></div><div class="plan-range"><b>{{Math.min(...plan.steps.map(s=>s.watts))}}–{{Math.max(...plan.steps.map(s=>s.watts))}} W</b><span>{{plan.requires_ftp?'BEISPIELWERTE':plan.meta?.relative_ftp?'RELATIV ZU DEINER FTP':'ABSOLUTE WATT'}}</span></div><p>{{plan.meta?.description||plan.steps.map(s=>s.name).filter((s,i,a)=>a.indexOf(s)===i).join(' · ')}}</p><button class="button" :class="selected===plan.id?'primary':'secondary'" @click="choosePlan(plan)"><Check v-if="selected===plan.id" :size="16"/>{{selected===plan.id?'Ausgewählt':'Vorschau & auswählen'}}<ChevronRight :size="16"/></button></article></div><p v-if="!visiblePlans.length" class="empty-plans">Für diese Kombination gibt es noch keinen Plan.</p>
    <section class="training-advice card"><h3>Was hilft beim Konditionsaufbau?</h3><p>Ruhige Ausdauer ist die Basis; intensivere Intervalle ergänzen sie. Beginne passend zu deinem Trainingsstand und lege zwischen harten Einheiten Erholung ein. Beim lockeren Training solltest du noch sprechen können. Die 4×4-Idee stammt aus dem NTNU-Programm; unsere Dauer- und Wattvarianten sind angepasste Vorschläge.</p><p>Bei VO₂max-orientierten Intervallen steigt der Puls verzögert: 85–95 % HFmax werden laut NTNU erst im späteren Intervall angestrebt. Nicht sofort hohe Watt nachlegen. Intensives Training setzt entsprechende Belastbarkeit voraus; bei Herzproblemen oder pulsbeeinflussenden Medikamenten Ziele ärztlich abstimmen.</p><p class="source-links"><a href="https://www.ntnu.edu/cerg/regimen" target="_blank" rel="noopener">NTNU · 4×4 & Aufbauprogramm ↗</a><a href="https://www.heart.org/en/healthy-living/exercise-and-physical-activity/fitness-basics/target-heart-rates" target="_blank" rel="noopener">AHA · persönliche Pulsziele ↗</a><a href="https://www.cdc.gov/physical-activity-basics/measuring/index.html" target="_blank" rel="noopener">CDC · Sprechtest ↗</a></p><small>Die App misst oder schätzt keine VO₂max. Eine Verbesserung ist ein Trainingsziel, kein zugesichertes Ergebnis.</small></section>
   </template>
'''+s[end:]

profile_ui='''
   <template v-if="modal==='profile'"><span class="eyebrow">DEINE BASIS FÜR PASSENDES TRAINING</span><h2>Persönliche Trainingswerte</h2><p>Trage bekannte Werte ein. Die App berechnet keine HFmax aus dem Alter und führt keinen Maximaltest durch. FTP ist deine bekannte funktionelle Schwellenleistung, kein Wunschwert.</p><div class="profile-fields"><label>FTP / Schwellenleistung (W)<input v-model.number="profileForm.ftp_watts" type="number" min="50" max="400" placeholder="Noch nicht hinterlegt"></label><label>Persönliche HFmax (bpm)<input v-model.number="profileForm.hr_max" type="number" min="100" max="230" placeholder="Bekannter individueller Wert"></label><label>Persönliche Pulsgrenze (bpm)<input v-model.number="profileForm.hr_ceiling" type="number" min="70" max="220" placeholder="Automatischer Stopp ab diesem Wert"></label><label>Minimale Leistung im Pulsmodus (W)<input v-model.number="profileForm.hr_min_watts" type="number" min="25" max="200"></label><label>Maximale Leistung im Pulsmodus (W)<input v-model.number="profileForm.hr_max_watts" type="number" min="30" max="400"></label></div><p>Bei fehlendem Signal wird auf 25 W reduziert und pausiert. Die Pulsgrenze ist eine technische Stoppbedingung und ersetzt keine medizinische Überwachung. Hohe Zielzonen werden unter dieser Grenze gedeckelt.</p><button class="button primary" :disabled="busy||state.running" @click="saveProfile">Persönliche Werte speichern <Check :size="17"/></button></template>
'''
s=s.replace("   <template v-if=\"modal==='settings'\">",profile_ui+"   <template v-if=\"modal==='settings'\">")
s=s.replace('<h2>Studio-Einstellungen</h2>','<h2>Studio-Einstellungen</h2><button class="button secondary" @click="openProfile">Persönliche Trainingswerte</button>')
p.write_text(s,encoding='utf-8')
